patch.find:
def rsi(c, n=14):
    if len(c) < n + 1:
        return None
    g = s = 0.0
    for i in range(len(c) - n, len(c)):
        ch = c[i] - c[i - 1]
        g += max(ch, 0.0); s += max(-ch, 0.0)
    if s == 0:
        return 100.0
    rs = (g / n) / (s / n)
    return 100 - 100 / (1 + rs)

