    bucket = min(90, max(10, int(round(conf * 100 / 10) * 10)))
    rec = bins.get(str(bucket)) or bins.get(bucket)
    if rec and rec.get("n", 0) >= 20:
        return rec["wins"] / rec["n"] / max(0.05, conf)
    return float(self.know["calibration"].get("factor", 1.0))

